window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a895c84a760a16f7"]={"versions": [{"id": "FIG-a895c84a760a16f7", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des Steuerungsablaufs zum Deaktivieren (Idle-Zustand) und Reaktivieren eines PWM-Kanals im MCAL (Microcontroller Abstraction Layer).</li>\n<li><strong>Architektur-Einordnung:</strong> Schnittstelle zwischen oberen Schichten (z. B. I/O Hardware Abstraction <code>IoHwAb</code>, Complex Device Driver <code>CDD</code> oder Applikations-SW-C via RTE) und dem hardwarenahen PWM-Treiber (<code>Pwm</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure / Lebenslinien:</strong></li>\n<li><code>Pwm User</code>: Aufrufende Instanz oberhalb des MCAL (typischerweise BSW <code>IoHwAb</code> oder <code>CDD</code>).</li>\n<li><code>«module» Pwm</code>: AUTOSAR Classic Basic Software Module (MCAL-Treiber zur Ansteuerung hardwarebasierter Timer-/PWM-Einheiten).</li>\n<li><strong>Verwendete Schnittstellen (C-APIs):</strong></li>\n<li><code>void Pwm_SetOutputToIdle(Pwm_ChannelType ChannelNumber)</code>: Versetzt den spezifizierten Kanal unmittelbar in den konfigurierten Ruhezustand.</li>\n<li><code>void Pwm_SetPeriodAndDuty(Pwm_ChannelType ChannelNumber, Pwm_PeriodType Period, uint16 DutyCycle)</code>: Synchroner Dienst zur Neukonfiguration von Periodendauer und Tastverhältnis (skaliert von <code>0x0000</code> = 0 % bis <code>0x8000</code> = 100 %).</li>\n<li><strong>Assoziierte Metadaten / Annotationen:</strong></li>\n<li>Diagramm-Metadatenbox: Status/Historie (<code>proposed by DB as per SWS Pwm Driver 1.0.9</code>, Zweck: Signal-Deaktivierung).</li>\n<li>Spezifikationsnotizen zum Ausgangspegel und zur Signal-Reaktivierung.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Idle-Trigger:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Pwm User</code> führt synchronen Aufruf <code>Pwm_SetOutputToIdle(ChannelNumber)</code> aus.</li>\n<li><code>Pwm</code>-Treiber stoppt die Signalmodulation des Kanals und legt den Ausgang unmittelbar auf den vorkonfigurierten Pegel (<code>PwmIdleState</code>: <code>PWM_LOW</code> oder <code>PWM_HIGH</code>).</li>\n<li>Rückkehr des Aufrufs an den Caller (<code>Pwm_SetOutputToIdle()</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Kanalzustand im Ruhezustand:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Hardware-Pin verharrt statisch auf dem Idle-Pegel. Laufende Flankenwechsel und periodische Channel-Notifications (Interrupts) für diesen Kanal sind suspendiert.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Reaktivierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zur Wiederaufnahme der Signalerzeugung ruft der <code>Pwm User</code> synchron <code>Pwm_SetPeriodAndDuty(...)</code> (oder alternativ <code>Pwm_SetDutyCycle</code>) auf.</li>\n<li>Der Treiber initialisiert Perioden- und Duty-Register der Hardware neu und startet die Wellenformgenerierung ab der nächsten Periodengrenze mit definierten Parametern.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Präprozessor- & Konfigurationsabhängigkeit:</strong></li>\n<li><code>Pwm_SetOutputToIdle</code> ist optional und erfordert <code>PwmSetOutputToIdleSupported == STD_ON</code> im Konfigurations-Containersatz (<code>PwmGeneral</code>).</li>\n<li><code>Pwm_SetPeriodAndDuty</code> erfordert <code>PwmSetPeriodAndDutySupported == STD_ON</code> sowie die Kanalklasse <code>PWM_VARIABLE_PERIOD</code> (<code>PwmChannelClass</code>). Für Kanäle mit fixer Periode ist zur Reaktivierung <code>Pwm_SetDutyCycle()</code> zu verwenden.</li>\n<li><strong>Kanal-Ruhepegel (<code>PwmIdleState</code>):</strong></li>\n<li>Der physikalische Ausgangszustand wird statisch im EcuC-Parameter <code>PwmIdleState</code> (<code>PWM_HIGH</code> / <code>PWM_LOW</code>) definiert und darf nicht mit einem Duty-Cycle von 0 % verwechselt werden (Polaritätsabhängigkeit über <code>PwmPolarity</code>).</li>\n<li><strong>Fehlerbehandlung (DET):</strong></li>\n<li>Uninitialisierter Aufruf führt zu <code>PWM_E_UNINIT</code>.</li>\n<li>Ungültiger Kanalparameter führt zu <code>PWM_E_PARAM_CHANNEL</code>.</li>\n<li>Bei Aufruf von <code>Pwm_SetPeriodAndDuty</code> an Kanälen ungleicher Klasse <code>PWM_VARIABLE_PERIOD</code> wird <code>PWM_E_PERIOD_UNCHANGEABLE</code> gemeldet.</li>\n</ul>"}, {"id": "FIG-40d96a04ce13c773", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des Steuerungsablaufs zum Deaktivieren (Idle-Zustand) und Reaktivieren eines PWM-Kanals im MCAL (Microcontroller Abstraction Layer).</li>\n<li><strong>Architektur-Einordnung:</strong> Schnittstelle zwischen oberen Schichten (z. B. I/O Hardware Abstraction <code>IoHwAb</code>, Complex Device Driver <code>CDD</code> oder Applikations-SW-C via RTE) und dem hardwarenahen PWM-Treiber (<code>Pwm</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure / Lebenslinien:</strong></li>\n<li><code>Pwm User</code>: Aufrufende Instanz oberhalb des MCAL (typischerweise BSW <code>IoHwAb</code> oder <code>CDD</code>).</li>\n<li><code>«module» Pwm</code>: AUTOSAR Classic Basic Software Module (MCAL-Treiber zur Ansteuerung hardwarebasierter Timer-/PWM-Einheiten).</li>\n<li><strong>Verwendete Schnittstellen (C-APIs):</strong></li>\n<li><code>void Pwm_SetOutputToIdle(Pwm_ChannelType ChannelNumber)</code>: Versetzt den spezifizierten Kanal unmittelbar in den konfigurierten Ruhezustand.</li>\n<li><code>void Pwm_SetPeriodAndDuty(Pwm_ChannelType ChannelNumber, Pwm_PeriodType Period, uint16 DutyCycle)</code>: Synchroner Dienst zur Neukonfiguration von Periodendauer und Tastverhältnis (skaliert von <code>0x0000</code> = 0 % bis <code>0x8000</code> = 100 %).</li>\n<li><strong>Assoziierte Metadaten / Annotationen:</strong></li>\n<li>Diagramm-Metadatenbox: Status/Historie (<code>proposed by DB as per SWS Pwm Driver 1.0.9</code>, Zweck: Signal-Deaktivierung).</li>\n<li>Spezifikationsnotizen zum Ausgangspegel und zur Signal-Reaktivierung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Idle-Trigger:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Pwm User</code> führt synchronen Aufruf <code>Pwm_SetOutputToIdle(ChannelNumber)</code> aus.</li>\n<li><code>Pwm</code>-Treiber stoppt die Signalmodulation des Kanals und legt den Ausgang unmittelbar auf den vorkonfigurierten Pegel (<code>PwmIdleState</code>: <code>PWM_LOW</code> oder <code>PWM_HIGH</code>).</li>\n<li>Rückkehr des Aufrufs an den Caller (<code>Pwm_SetOutputToIdle()</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Kanalzustand im Ruhezustand:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Hardware-Pin verharrt statisch auf dem Idle-Pegel. Laufende Flankenwechsel und periodische Channel-Notifications (Interrupts) für diesen Kanal sind suspendiert.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Reaktivierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zur Wiederaufnahme der Signalerzeugung ruft der <code>Pwm User</code> synchron <code>Pwm_SetPeriodAndDuty(...)</code> (oder alternativ <code>Pwm_SetDutyCycle</code>) auf.</li>\n<li>Der Treiber initialisiert Perioden- und Duty-Register der Hardware neu und startet die Wellenformgenerierung ab der nächsten Periodengrenze mit definierten Parametern.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Präprozessor- & Konfigurationsabhängigkeit:</strong></li>\n<li><code>Pwm_SetOutputToIdle</code> ist optional und erfordert <code>PwmSetOutputToIdleSupported == STD_ON</code> im Konfigurations-Containersatz (<code>PwmGeneral</code>).</li>\n<li><code>Pwm_SetPeriodAndDuty</code> erfordert <code>PwmSetPeriodAndDutySupported == STD_ON</code> sowie die Kanalklasse <code>PWM_VARIABLE_PERIOD</code> (<code>PwmChannelClass</code>). Für Kanäle mit fixer Periode ist zur Reaktivierung <code>Pwm_SetDutyCycle()</code> zu verwenden.</li>\n<li><strong>Kanal-Ruhepegel (<code>PwmIdleState</code>):</strong></li>\n<li>Der physikalische Ausgangszustand wird statisch im EcuC-Parameter <code>PwmIdleState</code> (<code>PWM_HIGH</code> / <code>PWM_LOW</code>) definiert und darf nicht mit einem Duty-Cycle von 0 % verwechselt werden (Polaritätsabhängigkeit über <code>PwmPolarity</code>).</li>\n<li><strong>Fehlerbehandlung (DET):</strong></li>\n<li>Uninitialisierter Aufruf führt zu <code>PWM_E_UNINIT</code>.</li>\n<li>Ungültiger Kanalparameter führt zu <code>PWM_E_PARAM_CHANNEL</code>.</li>\n<li>Bei Aufruf von <code>Pwm_SetPeriodAndDuty</code> an Kanälen ungleicher Klasse <code>PWM_VARIABLE_PERIOD</code> wird <code>PWM_E_PERIOD_UNCHANGEABLE</code> gemeldet.</li>\n</ul>"}, {"id": "FIG-0895d1f1bd670703", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des Steuerungsablaufs zum Deaktivieren (Idle-Zustand) und Reaktivieren eines PWM-Kanals im MCAL (Microcontroller Abstraction Layer).</li>\n<li><strong>Architektur-Einordnung:</strong> Schnittstelle zwischen oberen Schichten (z. B. I/O Hardware Abstraction <code>IoHwAb</code>, Complex Device Driver <code>CDD</code> oder Applikations-SW-C via RTE) und dem hardwarenahen PWM-Treiber (<code>Pwm</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure / Lebenslinien:</strong></li>\n<li><code>Pwm User</code>: Aufrufende Instanz oberhalb des MCAL (typischerweise BSW <code>IoHwAb</code> oder <code>CDD</code>).</li>\n<li><code>«module» Pwm</code>: AUTOSAR Classic Basic Software Module (MCAL-Treiber zur Ansteuerung hardwarebasierter Timer-/PWM-Einheiten).</li>\n<li><strong>Verwendete Schnittstellen (C-APIs):</strong></li>\n<li><code>void Pwm_SetOutputToIdle(Pwm_ChannelType ChannelNumber)</code>: Versetzt den spezifizierten Kanal unmittelbar in den konfigurierten Ruhezustand.</li>\n<li><code>void Pwm_SetPeriodAndDuty(Pwm_ChannelType ChannelNumber, Pwm_PeriodType Period, uint16 DutyCycle)</code>: Synchroner Dienst zur Neukonfiguration von Periodendauer und Tastverhältnis (skaliert von <code>0x0000</code> = 0 % bis <code>0x8000</code> = 100 %).</li>\n<li><strong>Assoziierte Metadaten / Annotationen:</strong></li>\n<li>Diagramm-Metadatenbox: Status/Historie (<code>proposed by DB as per SWS Pwm Driver 1.0.9</code>, Zweck: Signal-Deaktivierung).</li>\n<li>Spezifikationsnotizen zum Ausgangspegel und zur Signal-Reaktivierung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Idle-Trigger:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Pwm User</code> führt synchronen Aufruf <code>Pwm_SetOutputToIdle(ChannelNumber)</code> aus.</li>\n<li><code>Pwm</code>-Treiber stoppt die Signalmodulation des Kanals und legt den Ausgang unmittelbar auf den vorkonfigurierten Pegel (<code>PwmIdleState</code>: <code>PWM_LOW</code> oder <code>PWM_HIGH</code>).</li>\n<li>Rückkehr des Aufrufs an den Caller (<code>Pwm_SetOutputToIdle()</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Kanalzustand im Ruhezustand:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Hardware-Pin verharrt statisch auf dem Idle-Pegel. Laufende Flankenwechsel und periodische Channel-Notifications (Interrupts) für diesen Kanal sind suspendiert.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Reaktivierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zur Wiederaufnahme der Signalerzeugung ruft der <code>Pwm User</code> synchron <code>Pwm_SetPeriodAndDuty(...)</code> (oder alternativ <code>Pwm_SetDutyCycle</code>) auf.</li>\n<li>Der Treiber initialisiert Perioden- und Duty-Register der Hardware neu und startet die Wellenformgenerierung ab der nächsten Periodengrenze mit definierten Parametern.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Präprozessor- & Konfigurationsabhängigkeit:</strong></li>\n<li><code>Pwm_SetOutputToIdle</code> ist optional und erfordert <code>PwmSetOutputToIdleSupported == STD_ON</code> im Konfigurations-Containersatz (<code>PwmGeneral</code>).</li>\n<li><code>Pwm_SetPeriodAndDuty</code> erfordert <code>PwmSetPeriodAndDutySupported == STD_ON</code> sowie die Kanalklasse <code>PWM_VARIABLE_PERIOD</code> (<code>PwmChannelClass</code>). Für Kanäle mit fixer Periode ist zur Reaktivierung <code>Pwm_SetDutyCycle()</code> zu verwenden.</li>\n<li><strong>Kanal-Ruhepegel (<code>PwmIdleState</code>):</strong></li>\n<li>Der physikalische Ausgangszustand wird statisch im EcuC-Parameter <code>PwmIdleState</code> (<code>PWM_HIGH</code> / <code>PWM_LOW</code>) definiert und darf nicht mit einem Duty-Cycle von 0 % verwechselt werden (Polaritätsabhängigkeit über <code>PwmPolarity</code>).</li>\n<li><strong>Fehlerbehandlung (DET):</strong></li>\n<li>Uninitialisierter Aufruf führt zu <code>PWM_E_UNINIT</code>.</li>\n<li>Ungültiger Kanalparameter führt zu <code>PWM_E_PARAM_CHANNEL</code>.</li>\n<li>Bei Aufruf von <code>Pwm_SetPeriodAndDuty</code> an Kanälen ungleicher Klasse <code>PWM_VARIABLE_PERIOD</code> wird <code>PWM_E_PERIOD_UNCHANGEABLE</code> gemeldet.</li>\n</ul>"}, {"id": "FIG-a10beffcec959d97", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des Steuerungsablaufs zum Deaktivieren (Idle-Zustand) und Reaktivieren eines PWM-Kanals im MCAL (Microcontroller Abstraction Layer).</li>\n<li><strong>Architektur-Einordnung:</strong> Schnittstelle zwischen oberen Schichten (z. B. I/O Hardware Abstraction <code>IoHwAb</code>, Complex Device Driver <code>CDD</code> oder Applikations-SW-C via RTE) und dem hardwarenahen PWM-Treiber (<code>Pwm</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure / Lebenslinien:</strong></li>\n<li><code>Pwm User</code>: Aufrufende Instanz oberhalb des MCAL (typischerweise BSW <code>IoHwAb</code> oder <code>CDD</code>).</li>\n<li><code>«module» Pwm</code>: AUTOSAR Classic Basic Software Module (MCAL-Treiber zur Ansteuerung hardwarebasierter Timer-/PWM-Einheiten).</li>\n<li><strong>Verwendete Schnittstellen (C-APIs):</strong></li>\n<li><code>void Pwm_SetOutputToIdle(Pwm_ChannelType ChannelNumber)</code>: Versetzt den spezifizierten Kanal unmittelbar in den konfigurierten Ruhezustand.</li>\n<li><code>void Pwm_SetPeriodAndDuty(Pwm_ChannelType ChannelNumber, Pwm_PeriodType Period, uint16 DutyCycle)</code>: Synchroner Dienst zur Neukonfiguration von Periodendauer und Tastverhältnis (skaliert von <code>0x0000</code> = 0 % bis <code>0x8000</code> = 100 %).</li>\n<li><strong>Assoziierte Metadaten / Annotationen:</strong></li>\n<li>Diagramm-Metadatenbox: Status/Historie (<code>proposed by DB as per SWS Pwm Driver 1.0.9</code>, Zweck: Signal-Deaktivierung).</li>\n<li>Spezifikationsnotizen zum Ausgangspegel und zur Signal-Reaktivierung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Idle-Trigger:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Pwm User</code> führt synchronen Aufruf <code>Pwm_SetOutputToIdle(ChannelNumber)</code> aus.</li>\n<li><code>Pwm</code>-Treiber stoppt die Signalmodulation des Kanals und legt den Ausgang unmittelbar auf den vorkonfigurierten Pegel (<code>PwmIdleState</code>: <code>PWM_LOW</code> oder <code>PWM_HIGH</code>).</li>\n<li>Rückkehr des Aufrufs an den Caller (<code>Pwm_SetOutputToIdle()</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Kanalzustand im Ruhezustand:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Hardware-Pin verharrt statisch auf dem Idle-Pegel. Laufende Flankenwechsel und periodische Channel-Notifications (Interrupts) für diesen Kanal sind suspendiert.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Reaktivierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zur Wiederaufnahme der Signalerzeugung ruft der <code>Pwm User</code> synchron <code>Pwm_SetPeriodAndDuty(...)</code> (oder alternativ <code>Pwm_SetDutyCycle</code>) auf.</li>\n<li>Der Treiber initialisiert Perioden- und Duty-Register der Hardware neu und startet die Wellenformgenerierung ab der nächsten Periodengrenze mit definierten Parametern.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Präprozessor- & Konfigurationsabhängigkeit:</strong></li>\n<li><code>Pwm_SetOutputToIdle</code> ist optional und erfordert <code>PwmSetOutputToIdleSupported == STD_ON</code> im Konfigurations-Containersatz (<code>PwmGeneral</code>).</li>\n<li><code>Pwm_SetPeriodAndDuty</code> erfordert <code>PwmSetPeriodAndDutySupported == STD_ON</code> sowie die Kanalklasse <code>PWM_VARIABLE_PERIOD</code> (<code>PwmChannelClass</code>). Für Kanäle mit fixer Periode ist zur Reaktivierung <code>Pwm_SetDutyCycle()</code> zu verwenden.</li>\n<li><strong>Kanal-Ruhepegel (<code>PwmIdleState</code>):</strong></li>\n<li>Der physikalische Ausgangszustand wird statisch im EcuC-Parameter <code>PwmIdleState</code> (<code>PWM_HIGH</code> / <code>PWM_LOW</code>) definiert und darf nicht mit einem Duty-Cycle von 0 % verwechselt werden (Polaritätsabhängigkeit über <code>PwmPolarity</code>).</li>\n<li><strong>Fehlerbehandlung (DET):</strong></li>\n<li>Uninitialisierter Aufruf führt zu <code>PWM_E_UNINIT</code>.</li>\n<li>Ungültiger Kanalparameter führt zu <code>PWM_E_PARAM_CHANNEL</code>.</li>\n<li>Bei Aufruf von <code>Pwm_SetPeriodAndDuty</code> an Kanälen ungleicher Klasse <code>PWM_VARIABLE_PERIOD</code> wird <code>PWM_E_PERIOD_UNCHANGEABLE</code> gemeldet.</li>\n</ul>"}, {"id": "FIG-9b6f70ee510aa358", "releases": ["R20-11", "R21-11", "R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des Steuerungsablaufs zum Deaktivieren (Idle-Zustand) und Reaktivieren eines PWM-Kanals im MCAL (Microcontroller Abstraction Layer).</li>\n<li><strong>Architektur-Einordnung:</strong> Schnittstelle zwischen oberen Schichten (z. B. I/O Hardware Abstraction <code>IoHwAb</code>, Complex Device Driver <code>CDD</code> oder Applikations-SW-C via RTE) und dem hardwarenahen PWM-Treiber (<code>Pwm</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure / Lebenslinien:</strong></li>\n<li><code>Pwm User</code>: Aufrufende Instanz oberhalb des MCAL (typischerweise BSW <code>IoHwAb</code> oder <code>CDD</code>).</li>\n<li><code>«module» Pwm</code>: AUTOSAR Classic Basic Software Module (MCAL-Treiber zur Ansteuerung hardwarebasierter Timer-/PWM-Einheiten).</li>\n<li><strong>Verwendete Schnittstellen (C-APIs):</strong></li>\n<li><code>void Pwm_SetOutputToIdle(Pwm_ChannelType ChannelNumber)</code>: Versetzt den spezifizierten Kanal unmittelbar in den konfigurierten Ruhezustand.</li>\n<li><code>void Pwm_SetPeriodAndDuty(Pwm_ChannelType ChannelNumber, Pwm_PeriodType Period, uint16 DutyCycle)</code>: Synchroner Dienst zur Neukonfiguration von Periodendauer und Tastverhältnis (skaliert von <code>0x0000</code> = 0 % bis <code>0x8000</code> = 100 %).</li>\n<li><strong>Assoziierte Metadaten / Annotationen:</strong></li>\n<li>Diagramm-Metadatenbox: Status/Historie (<code>proposed by DB as per SWS Pwm Driver 1.0.9</code>, Zweck: Signal-Deaktivierung).</li>\n<li>Spezifikationsnotizen zum Ausgangspegel und zur Signal-Reaktivierung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Idle-Trigger:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Pwm User</code> führt synchronen Aufruf <code>Pwm_SetOutputToIdle(ChannelNumber)</code> aus.</li>\n<li><code>Pwm</code>-Treiber stoppt die Signalmodulation des Kanals und legt den Ausgang unmittelbar auf den vorkonfigurierten Pegel (<code>PwmIdleState</code>: <code>PWM_LOW</code> oder <code>PWM_HIGH</code>).</li>\n<li>Rückkehr des Aufrufs an den Caller (<code>Pwm_SetOutputToIdle()</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Kanalzustand im Ruhezustand:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Hardware-Pin verharrt statisch auf dem Idle-Pegel. Laufende Flankenwechsel und periodische Channel-Notifications (Interrupts) für diesen Kanal sind suspendiert.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Reaktivierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zur Wiederaufnahme der Signalerzeugung ruft der <code>Pwm User</code> synchron <code>Pwm_SetPeriodAndDuty(...)</code> (oder alternativ <code>Pwm_SetDutyCycle</code>) auf.</li>\n<li>Der Treiber initialisiert Perioden- und Duty-Register der Hardware neu und startet die Wellenformgenerierung ab der nächsten Periodengrenze mit definierten Parametern.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Präprozessor- & Konfigurationsabhängigkeit:</strong></li>\n<li><code>Pwm_SetOutputToIdle</code> ist optional und erfordert <code>PwmSetOutputToIdleSupported == STD_ON</code> im Konfigurations-Containersatz (<code>PwmGeneral</code>).</li>\n<li><code>Pwm_SetPeriodAndDuty</code> erfordert <code>PwmSetPeriodAndDutySupported == STD_ON</code> sowie die Kanalklasse <code>PWM_VARIABLE_PERIOD</code> (<code>PwmChannelClass</code>). Für Kanäle mit fixer Periode ist zur Reaktivierung <code>Pwm_SetDutyCycle()</code> zu verwenden.</li>\n<li><strong>Kanal-Ruhepegel (<code>PwmIdleState</code>):</strong></li>\n<li>Der physikalische Ausgangszustand wird statisch im EcuC-Parameter <code>PwmIdleState</code> (<code>PWM_HIGH</code> / <code>PWM_LOW</code>) definiert und darf nicht mit einem Duty-Cycle von 0 % verwechselt werden (Polaritätsabhängigkeit über <code>PwmPolarity</code>).</li>\n<li><strong>Fehlerbehandlung (DET):</strong></li>\n<li>Uninitialisierter Aufruf führt zu <code>PWM_E_UNINIT</code>.</li>\n<li>Ungültiger Kanalparameter führt zu <code>PWM_E_PARAM_CHANNEL</code>.</li>\n<li>Bei Aufruf von <code>Pwm_SetPeriodAndDuty</code> an Kanälen ungleicher Klasse <code>PWM_VARIABLE_PERIOD</code> wird <code>PWM_E_PERIOD_UNCHANGEABLE</code> gemeldet.</li>\n</ul>"}, {"id": "FIG-97804d3dfd2ac3db", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des Steuerungsablaufs zum Deaktivieren (Idle-Zustand) und Reaktivieren eines PWM-Kanals im MCAL (Microcontroller Abstraction Layer).</li>\n<li><strong>Architektur-Einordnung:</strong> Schnittstelle zwischen oberen Schichten (z. B. I/O Hardware Abstraction <code>IoHwAb</code>, Complex Device Driver <code>CDD</code> oder Applikations-SW-C via RTE) und dem hardwarenahen PWM-Treiber (<code>Pwm</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure / Lebenslinien:</strong></li>\n<li><code>Pwm User</code>: Aufrufende Instanz oberhalb des MCAL (typischerweise BSW <code>IoHwAb</code> oder <code>CDD</code>).</li>\n<li><code>«module» Pwm</code>: AUTOSAR Classic Basic Software Module (MCAL-Treiber zur Ansteuerung hardwarebasierter Timer-/PWM-Einheiten).</li>\n<li><strong>Verwendete Schnittstellen (C-APIs):</strong></li>\n<li><code>void Pwm_SetOutputToIdle(Pwm_ChannelType ChannelNumber)</code>: Versetzt den spezifizierten Kanal unmittelbar in den konfigurierten Ruhezustand.</li>\n<li><code>void Pwm_SetPeriodAndDuty(Pwm_ChannelType ChannelNumber, Pwm_PeriodType Period, uint16 DutyCycle)</code>: Synchroner Dienst zur Neukonfiguration von Periodendauer und Tastverhältnis (skaliert von <code>0x0000</code> = 0 % bis <code>0x8000</code> = 100 %).</li>\n<li><strong>Assoziierte Metadaten / Annotationen:</strong></li>\n<li>Diagramm-Metadatenbox: Status/Historie (<code>proposed by DB as per SWS Pwm Driver 1.0.9</code>, Zweck: Signal-Deaktivierung).</li>\n<li>Spezifikationsnotizen zum Ausgangspegel und zur Signal-Reaktivierung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Idle-Trigger:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>Pwm User</code> führt synchronen Aufruf <code>Pwm_SetOutputToIdle(ChannelNumber)</code> aus.</li>\n<li><code>Pwm</code>-Treiber stoppt die Signalmodulation des Kanals und legt den Ausgang unmittelbar auf den vorkonfigurierten Pegel (<code>PwmIdleState</code>: <code>PWM_LOW</code> oder <code>PWM_HIGH</code>).</li>\n<li>Rückkehr des Aufrufs an den Caller (<code>Pwm_SetOutputToIdle()</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Kanalzustand im Ruhezustand:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der Hardware-Pin verharrt statisch auf dem Idle-Pegel. Laufende Flankenwechsel und periodische Channel-Notifications (Interrupts) für diesen Kanal sind suspendiert.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Reaktivierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Zur Wiederaufnahme der Signalerzeugung ruft der <code>Pwm User</code> synchron <code>Pwm_SetPeriodAndDuty(...)</code> (oder alternativ <code>Pwm_SetDutyCycle</code>) auf.</li>\n<li>Der Treiber initialisiert Perioden- und Duty-Register der Hardware neu und startet die Wellenformgenerierung ab der nächsten Periodengrenze mit definierten Parametern.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Präprozessor- & Konfigurationsabhängigkeit:</strong></li>\n<li><code>Pwm_SetOutputToIdle</code> ist optional und erfordert <code>PwmSetOutputToIdleSupported == STD_ON</code> im Konfigurations-Containersatz (<code>PwmGeneral</code>).</li>\n<li><code>Pwm_SetPeriodAndDuty</code> erfordert <code>PwmSetPeriodAndDutySupported == STD_ON</code> sowie die Kanalklasse <code>PWM_VARIABLE_PERIOD</code> (<code>PwmChannelClass</code>). Für Kanäle mit fixer Periode ist zur Reaktivierung <code>Pwm_SetDutyCycle()</code> zu verwenden.</li>\n<li><strong>Kanal-Ruhepegel (<code>PwmIdleState</code>):</strong></li>\n<li>Der physikalische Ausgangszustand wird statisch im EcuC-Parameter <code>PwmIdleState</code> (<code>PWM_HIGH</code> / <code>PWM_LOW</code>) definiert und darf nicht mit einem Duty-Cycle von 0 % verwechselt werden (Polaritätsabhängigkeit über <code>PwmPolarity</code>).</li>\n<li><strong>Fehlerbehandlung (DET):</strong></li>\n<li>Uninitialisierter Aufruf führt zu <code>PWM_E_UNINIT</code>.</li>\n<li>Ungültiger Kanalparameter führt zu <code>PWM_E_PARAM_CHANNEL</code>.</li>\n<li>Bei Aufruf von <code>Pwm_SetPeriodAndDuty</code> an Kanälen ungleicher Klasse <code>PWM_VARIABLE_PERIOD</code> wird <code>PWM_E_PERIOD_UNCHANGEABLE</code> gemeldet.</li>\n</ul>"}], "trans": [{"from": "FIG-a895c84a760a16f7", "to": "FIG-40d96a04ce13c773", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-40d96a04ce13c773", "to": "FIG-0895d1f1bd670703", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-0895d1f1bd670703", "to": "FIG-a10beffcec959d97", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Notizfelder: Zeilenumbrüche im Fließtext der beiden Erläuterungsnotizen zur PWM-Zustandssteuerung und Signal-Reaktivierung redaktionell angepasst.</li>\n</ul>"}, {"from": "FIG-a10beffcec959d97", "to": "FIG-9b6f70ee510aa358", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-9b6f70ee510aa358", "to": "FIG-97804d3dfd2ac3db", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><code>«module» Pwm</code>: Das UML-Komponentensymbol in der rechten unteren Ecke des Lebenslinien-Kopfelements wurde entfernt.</li>\n<li>Diagramm-Layout: Erneuter Export mit angepasster Skalierung und aktualisierter Schriftartendarstellung.</li>\n</ul>"}]};
